{"protocolSection":{"identificationModule":{"nctId":"NCT02277743","orgStudyIdInfo":{"id":"R668-AD-1334"},"organization":{"fullName":"Regeneron Pharmaceuticals","class":"INDUSTRY"},"briefTitle":"Study of Dupilumab Monotherapy Administered to Adult Patients With Moderate-to-Severe Atopic Dermatitis","officialTitle":"A Phase 3 Confirmatory Study Investigating the Efficacy and Safety of Dupilumab Monotherapy Administered to Adult Patients With Moderate-to-Severe Atopic Dermatitis","acronym":"SOLO 1"},"statusModule":{"statusVerifiedDate":"2017-11","overallStatus":"COMPLETED","expandedAccessInfo":{"hasExpandedAccess":false},"startDateStruct":{"date":"2014-10"},"primaryCompletionDateStruct":{"date":"2015-11","type":"ACTUAL"},"completionDateStruct":{"date":"2016-02","type":"ACTUAL"},"studyFirstSubmitDate":"2014-10-27","studyFirstSubmitQcDate":"2014-10-28","studyFirstPostDateStruct":{"date":"2014-10-29","type":"ESTIMATED"},"resultsFirstSubmitDate":"2017-08-08","resultsFirstSubmitQcDate":"2017-11-17","resultsFirstPostDateStruct":{"date":"2017-11-21","type":"ACTUAL"},"dispFirstSubmitDate":"2017-01-13","dispFirstSubmitQcDate":"2017-01-13","dispFirstPostDateStruct":{"date":"2017-01-16","type":"ESTIMATED"},"lastUpdateSubmitDate":"2017-11-17","lastUpdatePostDateStruct":{"date":"2017-11-21","type":"ACTUAL"}},"sponsorCollaboratorsModule":{"responsibleParty":{"type":"SPONSOR"},"leadSponsor":{"name":"Regeneron Pharmaceuticals","class":"INDUSTRY"},"collaborators":[{"name":"Sanofi","class":"INDUSTRY"}]},"oversightModule":{"oversightHasDmc":true,"isFdaRegulatedDrug":true,"isFdaRegulatedDevice":false,"isUsExport":true},"descriptionModule":{"briefSummary":"This is a randomized, double-blind, placebo-controlled, parallel group study to confirm the efficacy and safety of Dupilumab monotherapy in adults with moderate-to-severe atopic dermatitis (AD)."},"conditionsModule":{"conditions":["Dermatitis, Atopic"]},"designModule":{"studyType":"INTERVENTIONAL","phases":["PHASE3"],"designInfo":{"allocation":"RANDOMIZED","interventionModel":"PARALLEL","primaryPurpose":"TREATMENT","maskingInfo":{"masking":"TRIPLE","whoMasked":["PARTICIPANT","INVESTIGATOR","OUTCOMES_ASSESSOR"]}},"enrollmentInfo":{"count":671,"type":"ACTUAL"}},"armsInterventionsModule":{"armGroups":[{"label":"Placebo","type":"EXPERIMENTAL","description":"Two subcutaneous injections of Placebo (for Dupilumab) as a loading dose on Day 1 followed by a single injection once weekly (qw) from Week 1 to Week 15.","interventionNames":["Drug: Placebo (for Dupilumab)"]},{"label":"Dupilumab 300 mg once weekly (qw)","type":"EXPERIMENTAL","description":"Two subcutaneous injections of Dupilumab 300 mg (for a total of 600 mg) as a loading dose on Day 1, followed by a single 300 mg injection of Dupilumab qw from Week 1 to Week 15.","interventionNames":["Drug: Dupilumab"]},{"label":"Dupilumab 300 mg every 2 weeks (q2w)","type":"EXPERIMENTAL","description":"Two subcutaneous injections of Dupilumab 300 mg (for a total of 600 mg) as a loading dose on Day 1, followed by a placebo alternating with single 300 mg injection of Dupilumab qw from Week 1 to Week 15.","interventionNames":["Drug: Dupilumab","Drug: Placebo (for Dupilumab)"]}],"interventions":[{"type":"DRUG","name":"Dupilumab","description":"Subcutaneous injection alternated among the different quadrants of the abdomen, upper thighs and upper arms","armGroupLabels":["Dupilumab 300 mg every 2 weeks (q2w)","Dupilumab 300 mg once weekly (qw)"],"otherNames":["REGN668","SAR231893","DUPIXENT®"]},{"type":"DRUG","name":"Placebo (for Dupilumab)","description":"Subcutaneous injection alternated among the different quadrants of the abdomen, upper thighs and upper arms","armGroupLabels":["Dupilumab 300 mg every 2 weeks (q2w)","Placebo"]}]},"outcomesModule":{"primaryOutcomes":[{"measure":"Percentage of Participants With Investigator's Global Assessment (IGA) Score of "0" or "1" and Reduction From Baseline of ≥2 Points at Week 16","description":"IGA is an assessment scale used to determine severity of AD and clinical response to treatment on a 5-point scale (0 = clear; 1 = almost clear; 2 = mild; 3 = moderate; 4 = severe) based on erythema and papulation/infiltration. Therapeutic response is an IGA score of 0 (clear) or 1 (almost clear). Participants with IGA score of "0" or "1" and a reduction from baseline of ≥2 points at Week 16 were reported. Values after first rescue treatment were set to missing and participants with missing IGA scores at Week 16 were considered as non-responders.","timeFrame":"Week 16"}],"secondaryOutcomes":[{"measure":"Percentage of Participants With Eczema Area and Severity Index-75 (EASI-75) (≥75% Improvement From Baseline) at Week 16","description":"The EASI score was used to measure the severity and extent of AD and measured erythema, infiltration, excoriation and lichenification on 4 anatomic regions of the body: head, trunk, upper and lower extremities. The total EASI score ranges from 0 (minimum) to 72 (maximum) points, with the higher scores reflecting the worse severity of AD. EASI-75 responders were the participants who achieved ≥75% overall improvement in EASI score from baseline to Week 16. Values after first rescue treatment use were set to missing and participants with missing EASI score at Week 16 were considered as non-responders.","timeFrame":"Week 16"},{"measure":"Percentage of Participants With Improvement (Reduction ≥4 Points) of Pruritus Numerical Rating Scale (NRS) Score From Baseline to Week 16","description":"Pruritus NRS was an assessment tool that was used to report the intensity of a participant's pruritus (itch), both maximum and average intensity, during a 24-hour recall period. Participants were asked the following question: how would a participant rate his itch at the worst moment during the previous 24 hours (for maximum itch intensity on a scale of 0 - 10 \[0 = no itch; 10 = worst itch imaginable\]). Participants achieving a reduction of ≥4 points from baseline in weekly average of peak daily pruritus NRS score at Week 16 were reported. Values after first rescue treatment were set to missing and participants with missing peak NRS at Week 16 were considered as non-responders.","timeFrame":"Baseline to Week 16"},{"measure":"Percentage of Participants With Improvement (Reduction ≥3 Points) of Pruritus Numerical Rating Scale (NRS) Score From Baseline to Week 16","description":"Pruritus NRS was an assessment tool that was used to report the intensity of a participant's pruritus (itch), both maximum and average intensity, during a 24-hour recall period. Participants were asked the following question: how would a participant rate his itch at the worst moment during the previous 24 hours (for maximum itch intensity on a scale of 0 - 10 \[0 = no itch; 10 = worst itch imaginable\]). Participants achieving a reduction of ≥3 points from baseline in weekly average of peak daily pruritus NRS score at Week 16 were reported. Values after first rescue treatment were set to missing and participants with missing peak NRS at Week 16 were considered as non-responders.","timeFrame":"Baseline to Week 16"},{"measure":"Percent Change From Baseline in Peak Daily Pruritus Numerical Rating Scale (NRS) Score to Week 16","description":"Pruritus NRS was an assessment tool that was used to report the intensity of a participant's pruritus (itch), both maximum and average intensity, during a 24-hour recall period. Participants were asked the following question: how would a participant rate his itch at the worst moment during the previous 24 hours (for maximum itch intensity on a scale of 0 - 10 \[0 = no itch; 10 = worst itch imaginable\]).","timeFrame":"Baseline to Week 16"},{"measure":"Percentage of Participants With Improvement (Reduction ≥4 Points) of Pruritus Numerical Rating Scale (NRS) Score From Baseline to Week 4","description":"Pruritus NRS was an assessment tool that was used to report the intensity of a participant's pruritus (itch), both maximum and average intensity, during a 24-hour recall period. Participants were asked the following question: how would a participant rate his itch at the worst moment during the previous 24 hours (for maximum itch intensity on a scale of 0 - 10 \[0 = no itch; 10 = worst itch imaginable\]). Participants achieving a reduction of ≥4 points from baseline in weekly average of peak daily pruritus NRS score at Week 4 were reported. Values after first rescue treatment were set to missing and subjects with missing peak NRS at Week 4 were considered as non-responders.","timeFrame":"Baseline to Week 4"},{"measure":"Percentage of Participants With Improvement (Reduction ≥4 Points) of Pruritus Numerical Rating Scale (NRS) Score From Baseline to Week 2","description":"Pruritus NRS was an assessment tool that was used to report the intensity of a participant's pruritus (itch), both maximum and average intensity, during a 24-hour recall period. Participants were asked the following question: how would a participant rate his itch at the worst moment during the previous 24 hours (for maximum itch intensity on a scale of 0 - 10 \[0 = no itch; 10 = worst itch imaginable\]). Participants achieving a reduction of ≥4 points from baseline in weekly average of peak daily pruritus NRS score at Week 2 were reported. Values after first rescue treatment were set to missing and participants with missing peak NRS at Week 2 were considered as non-responders.","timeFrame":"Baseline to Week 2"},{"measure":"Change From Baseline in Peak Daily Pruritus Numerical Rating Scale (NRS) Score to Week 16","description":"Pruritus NRS was an assessment tool that was used to report the intensity of a participant's pruritus (itch), both maximum and average intensity, during a 24-hour recall period. Participants were asked the following question: how would a participant rate his itch at the worst moment during the previous 24 hours (for maximum itch intensity on a scale of 0 - 10 \[0 = no itch; 10 = worst itch imaginable\]).","timeFrame":"Baseline to Week 16"},{"measure":"Percent Change From Baseline in Eczema Area and Severity Index (EASI) Score to Week 16","description":"The EASI score was used to measure the severity and extent of AD and measured erythema, infiltration, excoriation and lichenification on 4 anatomic regions of the body: head, trunk, upper and lower extremities. The total EASI score ranges from 0 (minimum) to 72 (maximum) points, with the higher scores reflecting the worse severity of AD.","timeFrame":"Baseline to Week 16"},{"measure":"Percentage of Participants With Eczema Area and Severity Index-50 (EASI-50) (≥50% Improvement From Baseline) at Week 16","description":"The EASI score was used to measure the severity and extent of AD and measured erythema, infiltration, excoriation and lichenification on 4 anatomic regions of the body: head, trunk, upper and lower extremities. The total EASI score ranges from 0 (minimum) to 72 (maximum) points, with the higher scores reflecting the worse severity of AD. EASI-50 responders were the participants who achieved ≥50% overall improvement in EASI score from baseline to Week 16. Values after first rescue treatment were set to missing and participants with missing EASI-50 scores at Week 16 were considered as non-responders.","timeFrame":"Week 16"},{"measure":"Percentage of Participants With Eczema Area and Severity Index-90 (EASI-90) (≥90% Improvement From Baseline) at Week 16","description":"The EASI score was used to measure the severity and extent of AD and measured erythema, infiltration, excoriation and lichenification on 4 anatomic regions of the body: head, trunk, upper and lower extremities. The total EASI score ranges from 0 (minimum) to 72 (maximum) points, with the higher scores reflecting the worse severity of AD. EASI-90 responders were the participants who achieved ≥90% overall improvement in EASI score from baseline to Week 16. Values after first rescue treatment were set to missing and participants with missing EASI-90 scores at Week 16 were considered as non-responders.","timeFrame":"Week 16"},{"measure":"Change From Baseline in Percent Body Surface Area (BSA) to Week 16","description":"BSA affected by AD was assessed for each section of the body (the possible highest score for each region was: head and neck \[9%\], anterior trunk \[18%\], back \[18%\], upper limbs \[18%\], lower limbs \[36%\], and genitals \[1%\]). It was reported as a percentage of all major body sections combined.","timeFrame":"Baseline to Week 16"},{"measure":"Percent Change From Baseline in the SCORing Atopic Dermatitis (SCORAD) Score to Week 16","description":"SCORAD is a clinical tool for assessing the severity of AD developed by the European Task Force on Atopic Dermatitis (Severity scoring of atopic dermatitis: the SCORAD index). Consensus Report of the European Task Force on Atopic Dermatitis. Dermatology (Basel) 186 (1): 23-31. 1993. Extent and intensity of eczema as well as subjective signs (insomnia, etc.) are assessed and scored. Total score ranges from 0 (absent disease) to 103 (severe disease).","timeFrame":"Baseline to Week 16"},{"measure":"Change From Baseline in Dermatology Life Quality Index (DLQI) to Week 16","description":"The DLQI is a 10-item, validated questionnaire used in clinical practice and clinical trials to assess the impact of AD disease symptoms and treatment on quality of life (QOL). The 10 questions assessed QOL over the past week, with an overall scoring of 0 (absent disease) to 30 (severe disease); a high score was indicative of a poor QOL.","timeFrame":"Baseline to Week 16"},{"measure":"Change From Baseline in Patient Oriented Eczema Measure (POEM) to Week 16","description":"The POEM is a 7-item questionnaire that assesses disease symptoms (dryness, itching, flaking, cracking, sleep loss, bleeding and weeping) with a scoring system of 0 (absent disease) to 28 (severe disease) (high score indicative of poor quality of life \[QOL\]).","timeFrame":"Baseline to Week 16"},{"measure":"Change From Baseline in Hospital Anxiety Depression Scale (HADS) to Week 16","description":"HADS is a fourteen item scale. Seven of the items relate to anxiety and seven items relate to depression. Each item on the questionnaire is scored from 0 (minimum score) - 3 (maximum score) and this means that a person can score between 0 (no symptoms) and 21 (severe symptoms) for either anxiety or depression. Cut-offs for identifying psychiatric distress has been reported as 7 to 8 for possible presence, 10 to 11 for probable presence, and 14 to 15 for severe anxiety or depression.","timeFrame":"Baseline to Week 16"},{"measure":"Percent Change From Baseline in Global Individual Signs Score (GISS) to Week 16","description":"Individual components of the AD lesions (erythema, infiltration/ papulation, excoriations, and lichenification) were rated globally (each assessed for the whole body, not by anatomical region) on a 4-point scale (0= none, 1= mild, 2= moderate and 3= severe) using the EASI severity grading criteria. Total score ranges from 0 (absent disease) to 12 (severe disease).","timeFrame":"Baseline to Week 16"},{"measure":"Percent Change From Baseline in Peak Daily Pruritus NRS Score to Week 2","description":"Pruritus NRS was an assessment tool that was used to report the intensity of a participant's pruritus (itch), both maximum and average intensity, during a 24-hour recall period. Participants were asked the following question: how would a participant rate his itch at the worst moment during the previous 24 hours (for maximum itch intensity on a scale of 0 - 10 \[0 = no itch; 10 = worst itch imaginable\]).","timeFrame":"Baseline to Week 2"},{"measure":"Percentage of Participants With Skin Infection Treatment Emergent Adverse Events (TEAEs) Requiring Systemic Treatment","description":"Treatment-emergent adverse events (TEAEs) were defined as AEs that developed or worsened or became serious during on-treatment period (time from the first dose of study drug up to the end of study \[Week 28\]). A serious adverse event (SAE) was defined as any untoward medical occurrence that resulted in any of the following outcomes: death, life-threatening, required initial or prolonged in-patient hospitalization, persistent or significant disability/incapacity, congenital anomaly/birth defect, or considered as medically important event. Any TEAE included participants with both serious and non-serious AEs. Statistical significance in the hierarchical testing of secondary hypotheses was broken at this endpoint. Therefore, subsequent secondary efficacy endpoints were not tested for statistical significance.","timeFrame":"Baseline up to Week 16"},{"measure":"Percentage of Participants With Treatment Emergent Serious Adverse Events (TESAEs) From Baseline Through Week 16","description":"Any untoward medical occurrence in a participant who received investigational medicinal product (IMP) was considered an AE without regard to possibility of causal relationship with this treatment. Treatment-emergent adverse events (TEAEs) were defined as AEs that developed or worsened or became serious during on-treatment period (time from the first dose of study drug up to the end of study \[Week 28\]). A serious adverse event (SAE) was defined as any untoward medical occurrence that resulted in any of the following outcomes: death, life-threatening, required initial or prolonged in-patient hospitalization, persistent or significant disability/incapacity, congenital anomaly/birth defect, or considered as medically important event. Any TEAE included participants with both serious and non-serious AEs.","timeFrame":"Baseline up to Week 16"},{"measure":"Percentage of Participants With Treatment Emergent Adverse Events (TEAEs) Leading to Treatment Discontinuation From Baseline Through Week 16","description":"Any untoward medical occurrence in a participant who received investigational medicinal product (IMP) was considered an AE without regard to possibility of causal relationship with this treatment. Treatment-emergent adverse events (TEAEs) were defined as AEs that developed or worsened or became serious during on-treatment period (time from the first dose of study drug up to the end of study \[Week 28\]). A serious adverse event (SAE) was defined as any untoward medical occurrence that resulted in any of the following outcomes: death, life-threatening, required initial or prolonged in-patient hospitalization, persistent or significant disability/incapacity, congenital anomaly/birth defect, or considered as medically important event. Any TEAE included participants with both serious and non-serious AEs.","timeFrame":"Baseline up to Week 16"}]},"eligibilityModule":{"eligibilityCriteria":"Inclusion Criteria:

1. Male or female, 18 years or older
2. Chronic AD (according to American Academy of Dermatology Consensus Criteria Eichenfield 2014) that has been present for at least 3 years before the screening visit;
3. Eczema Area and Severity Index (EASI) Score ≥16 at the screening and baseline visits;
4. Investigator's Global Assessment (IGA) Score ≥3 (on the 0 to 4 IGA scale, in which 3 is moderate and 4 is severe) at the screening and baseline visits;
5. ≥10% body surface area (BSA) of AD involvement at the screening and baseline visits;
6. Documented recent history (within 6 months before the screening visit) of inadequate response to treatment with topical medications or for whom topical treatments are otherwise medically inadvisable (e.g, because of important side effects or safety risks).

Exclusion Criteria:

1. Participation in a prior Dupilumab clinical study;
2. Treatment with an investigational drug within 8 weeks or within 5 half-lives (if known), whichever was longer, before the baseline visit;
3. Having used any of the following treatments within 4 weeks before the baseline visit, or any condition that, in the opinion of the investigator, was likely to require such treatment(s) during the first 4 weeks of study treatment:

   * Immunosuppressive/ immunomodulating drugs (e.g, systemic corticosteroids, cyclosporine, mycophenolate-mofetil, IFN-γ, Janus kinase inhibitors, azathioprine, methotrexate, etc.);
   * Phototherapy for AD
4. Treatment with topical corticosteroids (TCS) or topical calcineurin inhibitors (TCI) within 1 week before the baseline visit;
5. Treatment with biologics as follows:

   * Any cell-depleting agents including but not limited to rituximab: within 6 months before the baseline visit, or until lymphocyte count returns to normal, whichever was longer
   * Other biologics: within 5 half-lives (if known) or 16 weeks prior to baseline visit, whichever was longer
6. Regular use (more than 2 visits per week) of a tanning booth/ parlor within 4 weeks of the screening visit;
7. Planned or anticipated use of any prohibited medications and procedures during study treatment;
8. Treatment with a live (attenuated) vaccine within 12 weeks before the baseline visit;
9. Active chronic or acute infection requiring treatment with systemic antibiotics, antivirals, antiparasitics, antiprotozoals, or antifungals within 2 weeks before the baseline visit, or superficial skin infections within 1 week before the baseline visit. NOTE: Participants might be rescreened after infection resolves;
10. Known or suspected history of immunosuppression, including history of invasive opportunistic infections (e.g, tuberculosis \[TB\], histoplasmosis, listeriosis, coccidioidomycosis, pneumocystosis, aspergillosis) despite infection resolution: or unusually frequent, recurrent, or prolonged infections, per investigator judgment;
11. History of human immunodeficiency virus (HIV) infection or positive HIV serology at screening;
12. Positive with hepatitis B surface antigen (HBsAg) or hepatitis C antibody at the screening visit;
13. Participant was a member of the investigational team or his/her immediate family;
14. Pregnant or breastfeeding women, or women planning to become pregnant or breastfeed during the study;
15. Women unwilling to use adequate birth control, if of reproductive potential and sexually active.

Note: The information listed above is not intended to contain all considerations relevant to a participant's potential participation in this clinical trial therefore not all inclusion/ exclusion criteria are listed.","healthyVolunteers":false,"sex":"ALL","minimumAge":"18 Years","stdAges":["ADULT","OLDER_ADULT"]},"contactsLocationsModule":{"overallOfficials":[{"name":"Clinical Trial Management","affiliation":"Regeneron Pharmaceuticals","role":"STUDY_DIRECTOR"}],"locations":[{"city":"Birmingham","state":"Alabama","country":"United States","geoPoint":{"lat":33.52066,"lon":-86.80249}},{"city":"Fort Smith","state":"Arkansas","country":"United States","geoPoint":{"lat":35.38592,"lon":-94.39855}},{"city":"Rogers","state":"Arkansas","country":"United States","geoPoint":{"lat":36.33202,"lon":-94.11854}},{"city":"Clovis","state":"California","country":"United States","geoPoint":{"lat":36.82523,"lon":-119.70292}},{"city":"Lomita","state":"California","country":"United States","geoPoint":{"lat":33.79224,"lon":-118.31507}},{"city":"Los Angeles","state":"California","country":"United States","geoPoint":{"lat":34.05223,"lon":-118.24368}},{"city":"Oceanside","state":"California","country":"United States","geoPoint":{"lat":33.19587,"lon":-117.37948}},{"city":"Palmdale","state":"California","country":"United States","geoPoint":{"lat":34.57943,"lon":-118.11646}},{"city":"Rolling Hills Estates","state":"California","country":"United States","geoPoint":{"lat":33.78779,"lon":-118.35813}},{"city":"San Diego","state":"California","country":"United States","geoPoint":{"lat":32.71571,"lon":-117.16472}},{"city":"Santa Monica","state":"California","country":"United States","geoPoint":{"lat":34.01949,"lon":-118.49138}},{"city":"Stockton","state":"California","country":"United States","geoPoint":{"lat":37.9577,"lon":-121.29078}},{"city":"Boca Raton","state":"Florida","country":"United States","geoPoint":{"lat":26.35869,"lon":-80.0831}},{"city":"Clearwater","state":"Florida","country":"United Sta