{"protocolSection":{"identificationModule":{"nctId":"NCT03703102","orgStudyIdInfo":{"id":"4083-006"},"organization":{"fullName":"Kyowa Kirin Co., Ltd.","class":"INDUSTRY"},"briefTitle":"Study of an Anti-OX40 Monoclonal Antibody (KHK4083) in Subjects With Moderate to Severe Atopic Dermatitis","officialTitle":"A Phase 2, Multicenter, Randomized, Double-blind, Parallel-group, Placebo-controlled Study of an Anti-OX40 Monoclonal Antibody (KHK4083) in Subjects With Moderate to Severe Atopic Dermatitis (AD)"},"statusModule":{"statusVerifiedDate":"2024-04","overallStatus":"COMPLETED","expandedAccessInfo":{"hasExpandedAccess":false},"startDateStruct":{"date":"2018-10-22","type":"ACTUAL"},"primaryCompletionDateStruct":{"date":"2020-02-06","type":"ACTUAL"},"completionDateStruct":{"date":"2020-11-12","type":"ACTUAL"},"studyFirstSubmitDate":"2018-10-09","studyFirstSubmitQcDate":"2018-10-09","studyFirstPostDateStruct":{"date":"2018-10-11","type":"ACTUAL"},"resultsFirstSubmitDate":"2022-03-22","resultsFirstSubmitQcDate":"2022-05-13","resultsFirstPostDateStruct":{"date":"2022-06-09","type":"ACTUAL"},"dispFirstSubmitDate":"2021-02-02","dispFirstSubmitQcDate":"2022-05-13","dispFirstPostDateStruct":{"date":"2022-06-09","type":"ACTUAL"},"lastUpdateSubmitDate":"2024-04-24","lastUpdatePostDateStruct":{"date":"2024-04-26","type":"ACTUAL"}},"sponsorCollaboratorsModule":{"responsibleParty":{"type":"SPONSOR"},"leadSponsor":{"name":"Kyowa Kirin, Inc.","class":"INDUSTRY"},"collaborators":[{"name":"Kyowa Kirin Co., Ltd.","class":"INDUSTRY"}]},"oversightModule":{"oversightHasDmc":false,"isFdaRegulatedDrug":true,"isFdaRegulatedDevice":false},"descriptionModule":{"briefSummary":"A Phase 2, multicenter, randomized, placebo-controlled, double-blind, parallel-group study for subjects with moderate to severe AD whose disease cannot be adequately controlled with topical medications or for whom topical treatment is medically inadvisable."},"conditionsModule":{"conditions":["Atopic Dermatitis"],"keywords":["AD","eczema","skin diseases","biologics"]},"designModule":{"studyType":"INTERVENTIONAL","phases":["PHASE2"],"designInfo":{"allocation":"RANDOMIZED","interventionModel":"PARALLEL","interventionModelDescription":"subcutaneous administration","primaryPurpose":"TREATMENT","maskingInfo":{"masking":"QUADRUPLE","whoMasked":["PARTICIPANT","CARE_PROVIDER","INVESTIGATOR","OUTCOMES_ASSESSOR"]}},"enrollmentInfo":{"count":274,"type":"ACTUAL"}},"armsInterventionsModule":{"armGroups":[{"label":"Arm A","type":"PLACEBO_COMPARATOR","description":"Subcutaneous administration of placebo","interventionNames":["Drug: Placebo"]},{"label":"Arm B","type":"EXPERIMENTAL","description":"Subcutaneous administration of KHK4083 (dose level 1, dosing regimen 2)","interventionNames":["Drug: KHK4083"]},{"label":"Arm C","type":"EXPERIMENTAL","description":"Subcutaneous administration of KHK4083 (dose level 2, dosing regimen 1)","interventionNames":["Drug: KHK4083"]},{"label":"Arm D","type":"EXPERIMENTAL","description":"Subcutaneous administration of KHK4083 (dose level 3, dosing regimen 1)","interventionNames":["Drug: KHK4083"]},{"label":"Arm E","type":"EXPERIMENTAL","description":"Subcutaneous administration of KHK4083 (dose level 3, dosing regimen 2)","interventionNames":["Drug: KHK4083"]}],"interventions":[{"type":"DRUG","name":"KHK4083","description":"Anti-OX40 Monoclonal Antibody KHK4083","armGroupLabels":["Arm B","Arm C","Arm D","Arm E"]},{"type":"DRUG","name":"Placebo","description":"Matching placebo","armGroupLabels":["Arm A"]}]},"outcomesModule":{"primaryOutcomes":[{"measure":"Percent Change From Baseline to Week 16 in Eczema Area and Severity Index (EASI) Score","description":"In the EASI assessment, the severity of 4 elements of eczema (erythema, induration/papulation, excoriation, and lichenification) at each of 4 body regions (head and neck, trunk, upper extremities, and lower extremities) will be assessed on a scale of 0 to 3 (0 = None , 1 = Mild, 2 = Moderate, 3 = Severe). Half scores (1.5 and 2.5) are allowed, with the exception of 0.5. Any signs must be at least 1 (mild) in severity. In addition, the extent of eczema at each of the 4 body regions will be assessed on a scale of 0 to 6 (0 = 0%, 1 = 1% to 9%, 2 = 10% to 29%, 3 = 30% to 49%, 4 = 50% to 69%, 5 = 70% to 89%, 6 = 90% to 100%). Scores calculated according to the expression "total score of 4 elements of eczema × area score of eczema" will be multiplied by 0.1 for head and neck, 0.2 for upper extremities, 0.3 for trunk, and 0.4 for lower extremities. The 4 region scores obtained will then be summed up (maximum score: 72) as EASI score.","timeFrame":"Baseline to Week 16"}],"secondaryOutcomes":[{"measure":"Achievement of 50%, 75%, or 90% Reduction From Baseline in Eczema Area and Severity Index (EASI) Score (EASI-50, EASI-75, or EASI-90) at Week 16","description":"In the EASI assessment, the severity of 4 elements of eczema (erythema, induration/papulation, excoriation, and lichenification) at each of 4 body regions (head and neck, trunk, upper extremities, and lower extremities) will be assessed on a scale of 0 to 3 (0 = None , 1 = Mild, 2 = Moderate, 3 = Severe). Half scores (1.5 and 2.5) are allowed, with the exception of 0.5. Any signs must be at least 1 (mild) in severity. In addition, the extent of eczema at each of the 4 body regions will be assessed on a scale of 0 to 6 (0 = 0%, 1 = 1% to 9%, 2 = 10% to 29%, 3 = 30% to 49%, 4 = 50% to 69%, 5 = 70% to 89%, 6 = 90% to 100%). Scores calculated according to the expression "total score of 4 elements of eczema × area score of eczema" will be multiplied by 0.1 for head and neck, 0.2 for upper extremities, 0.3 for trunk, and 0.4 for lower extremities. The 4 region scores obtained will then be summed up (maximum score: 72) as EASI score.","timeFrame":"Baseline to Week 16"},{"measure":"Change From Baseline to Week 16 in Eczema Area and Severity Index (EASI) Score","description":"In the EASI assessment, the severity of 4 elements of eczema (erythema, induration/papulation, excoriation, and lichenification) at each of 4 body regions (head and neck, trunk, upper extremities, and lower extremities) will be assessed on a scale of 0 to 3 (0 = None , 1 = Mild, 2 = Moderate, 3 = Severe). Half scores (1.5 and 2.5) are allowed, with the exception of 0.5. Any signs must be at least 1 (mild) in severity. In addition, the extent of eczema at each of the 4 body regions will be assessed on a scale of 0 to 6 (0 = 0%, 1 = 1% to 9%, 2 = 10% to 29%, 3 = 30% to 49%, 4 = 50% to 69%, 5 = 70% to 89%, 6 = 90% to 100%). Scores calculated according to the expression "total score of 4 elements of eczema × area score of eczema" will be multiplied by 0.1 for head and neck, 0.2 for upper extremities, 0.3 for trunk, and 0.4 for lower extremities. The 4 region scores obtained will then be summed up (maximum score: 72) as EASI score.","timeFrame":"Baseline to Week 16"},{"measure":"Change From Baseline to Week 16 in SCORing Atopic Dermatitis (SCORAD) Score","description":"In the SCORAD assessment, the extent of AD will be calculated as the sum of the percentage of each defined body area, with a maximum score of 100% (assigned as "A" in the overall SCORAD calculation). The severity of 6 specific symptoms of AD will be assessed using the following scale: 0 = none, 1 = mild, 2 = moderate, 3 = severe, with a maximum score of 18 (assigned as "B" in the overall SCORAD calculation). Itch and sleeplessness will be assessed by subjects on a visual analogue scale (VAS), where 0 is no itch (or sleeplessness) and 10 is the worst imaginable itch (or sleeplessness), with a maximum score of 20 (assigned as "C" in the overall SCORAD calculation). The SCORAD score is calculated as A/5 + 7B/2 + C. The maximum possible SCORAD score is 103; higher scores indicate poorer or more severe condition.","timeFrame":"Baseline to Week 16"},{"measure":"Percent Change From Baseline to Week 16 in SCORing Atopic Dermatitis (SCORAD) Score","description":"In the SCORAD assessment, the extent of AD will be calculated as the sum of the percentage of each defined body area, with a maximum score of 100% (assigned as "A" in the overall SCORAD calculation). The severity of 6 specific symptoms of AD will be assessed using the following scale: 0 = none, 1 = mild, 2 = moderate, 3 = severe, with a maximum score of 18 (assigned as "B" in the overall SCORAD calculation). Itch and sleeplessness will be assessed by subjects on a visual analogue scale (VAS), where 0 is no itch (or sleeplessness) and 10 is the worst imaginable itch (or sleeplessness), with a maximum score of 20 (assigned as "C" in the overall SCORAD calculation). The SCORAD score is calculated as A/5 + 7B/2 + C. The maximum possible SCORAD score is 103; higher scores indicate poorer or more severe condition.","timeFrame":"Baseline to Week 16"},{"measure":"Achievement of an Investigator's Global Assessment (IGA) Score of 0 or 1 and a Reduction From Baseline of ≥2 Points at Week 16","description":"In the IGA, the Investigator will evaluate the overall skin symptoms of subjects at each visit on a 5-point scale ranging from 0 (clear) to 4 (severe).","timeFrame":"Baseline to Week 16"},{"measure":"Change From Baseline to Week 16 in Percent Body Surface Area of Involvement of AD (BSA)","description":"The Investigator will calculate the percentage (%) of the total body surface area affected by AD.","timeFrame":"Baseline to Week 16"},{"measure":"Change From Baseline to Week 16 in Pruritus Numerical Rating Scale (NRS) Score","description":"The worst degree of itch experienced during 24 hours before the time point will be assessed on a Numerical Rating Scale. The degree of itch will be scored on an 11-point scale, with 0 being "no itch" and 10 being the "worst itch imaginable."","timeFrame":"Baseline to Week 16"},{"measure":"Percent Change From Baseline to Week 16 in Pruritus Numerical Rating Scale (NRS) Score","description":"The worst degree of itch experienced during 24 hours before the time point will be assessed on a Numerical Rating Scale. The degree of itch will be scored on an 11-point scale, with 0 being "no itch" and 10 being the "worst itch imaginable."","timeFrame":"Baseline to Week 16"},{"measure":"Change From Baseline to Week 16 in Sleep Disturbance Numerical Rating Scale (NRS) Score","description":"Daily sleep disturbance in the last 24 hours before the relevant time point will be assessed on a Numerical Rating Scale. Subjects will score the degree of their sleep disturbance on an 11-point scale ranging from 'no sleep loss' (0) to 'I cannot sleep at all' (10).","timeFrame":"Baseline to Week 16"},{"measure":"Percent Change From Baseline to Week 16 in Sleep Disturbance Numerical Rating Scale (NRS) Score","description":"Daily sleep disturbance in the last 24 hours before the relevant time point will be assessed on a Numerical Rating Scale. Subjects will score the degree of their sleep disturbance on an 11-point scale ranging from 'no sleep loss' (0) to 'I cannot sleep at all' (10).","timeFrame":"Baseline to Week 16"},{"measure":"Change From Baseline to Week 16 in Dermatology Life Quality Index (DLQI)","description":"DLQI consists of 6 subscales (symptoms and feelings, daily activities, leisure, work and school, personal relationships, and treatment), which are scored from 0 to 3 on the basis of 10 questions. The DLQI is calculated by summing the score of each question resulting in a maximum of 30 and a minimum of 0. The higher the score, the more QoL is impaired.","timeFrame":"Baseline to Week 16"},{"measure":"EASI Score at Each Time Point","description":"In the EASI assessment, the severity of 4 elements of eczema (erythema, induration/papulation, excoriation, and lichenification) at each of 4 body regions (head and neck, trunk, upper extremities, and lower extremities) will be assessed on a scale of 0 to 3 (0 = None , 1 = Mild, 2 = Moderate, 3 = Severe). Half scores (1.5 and 2.5) are allowed, with the exception of 0.5. Any signs must be at least 1 (mild) in severity. In addition, the extent of eczema at each of the 4 body regions will be assessed on a scale of 0 to 6 (0 = 0%, 1 = 1% to 9%, 2 = 10% to 29%, 3 = 30% to 49%, 4 = 50% to 69%, 5 = 70% to 89%, 6 = 90% to 100%). Scores calculated according to the expression "total score of 4 elements of eczema × area score of eczema" will be multiplied by 0.1 for head and neck, 0.2 for upper extremities, 0.3 for trunk, and 0.4 for lower extremities. The 4 region scores obtained will then be summed up (maximum score: 72) as EASI score.","timeFrame":"56 Weeks"},{"measure":"Percent Change From Baseline in EASI Score at Each Time Point","description":"In the EASI assessment, the severity of 4 elements of eczema (erythema, induration/papulation, excoriation, and lichenification) at each of 4 body regions (head and neck, trunk, upper extremities, and lower extremities) will be assessed on a scale of 0 to 3 (0 = None , 1 = Mild, 2 = Moderate, 3 = Severe). Half scores (1.5 and 2.5) are allowed, with the exception of 0.5. Any signs must be at least 1 (mild) in severity. In addition, the extent of eczema at each of the 4 body regions will be assessed on a scale of 0 to 6 (0 = 0%, 1 = 1% to 9%, 2 = 10% to 29%, 3 = 30% to 49%, 4 = 50% to 69%, 5 = 70% to 89%, 6 = 90% to 100%). Scores calculated according to the expression "total score of 4 elements of eczema × area score of eczema" will be multiplied by 0.1 for head and neck, 0.2 for upper extremities, 0.3 for trunk, and 0.4 for lower extremities. The 4 region scores obtained will then be summed up (maximum score: 72) as EASI score.","timeFrame":"56 Weeks"},{"measure":"Achievement of EASI-50, EASI-75, or EASI-90 at Each Time Point","description":"In the EASI assessment, the severity of 4 elements of eczema (erythema, induration/papulation, excoriation, and lichenification) at each of 4 body regions (head and neck, trunk, upper extremities, and lower extremities) will be assessed on a scale of 0 to 3 (0 = None , 1 = Mild, 2 = Moderate, 3 = Severe). Half scores (1.5 and 2.5) are allowed, with the exception of 0.5. Any signs must be at least 1 (mild) in severity. In addition, the extent of eczema at each of the 4 body regions will be assessed on a scale of 0 to 6 (0 = 0%, 1 = 1% to 9%, 2 = 10% to 29%, 3 = 30% to 49%, 4 = 50% to 69%, 5 = 70% to 89%, 6 = 90% to 100%).","timeFrame":"56 Weeks"},{"measure":"SCORing Atopic Dermatitis (SCORAD) Score at Each Time Point","description":"In the SCORAD assessment, the extent of AD will be calculated as the sum of the percentage of each defined body area, with a maximum score of 100% (assigned as "A" in the overall SCORAD calculation). The severity of 6 specific symptoms of AD will be assessed using the following scale: 0 = none, 1 = mild, 2 = moderate, 3 = severe, with a maximum score of 18 (assigned as "B" in the overall SCORAD calculation). Itch and sleeplessness will be assessed by subjects on a visual analogue scale (VAS), where 0 is no itch (or sleeplessness) and 10 is the worst imaginable itch (or sleeplessness), with a maximum score of 20 (assigned as "C" in the overall SCORAD calculation). The SCORAD score is calculated as A/5 + 7B/2 + C. The maximum possible SCORAD score is 103; higher scores indicate poorer or more severe condition.","timeFrame":"56 Weeks"},{"measure":"Percent Change From Baseline in SCORing Atopic Dermatitis (SCORAD) Score at Each Time Point","description":"In the SCORAD assessment, the extent of AD will be calculated as the sum of the percentage of each defined body area, with a maximum score of 100% (assigned as "A" in the overall SCORAD calculation). The severity of 6 specific symptoms of AD will be assessed using the following scale: 0 = none, 1 = mild, 2 = moderate, 3 = severe, with a maximum score of 18 (assigned as "B" in the overall SCORAD calculation). Itch and sleeplessness will be assessed by subjects on a visual analogue scale (VAS), where 0 is no itch (or sleeplessness) and 10 is the worst imaginable itch (or sleeplessness), with a maximum score of 20 (assigned as "C" in the overall SCORAD calculation). The SCORAD score is calculated as A/5 + 7B/2 + C. The maximum possible SCORAD score is 103; higher scores indicate poorer or more severe condition.","timeFrame":"56 Weeks"},{"measure":"Achievement of an Investigator's Global Assessment (IGA) Score of 0 or 1 and a Reduction From Baseline of ≥2 Points at Each Time Point","description":"In the IGA, the Investigator will evaluate the overall skin symptoms of subjects at each visit on a 5-point scale ranging from 0 (clear) to 4 (severe)","timeFrame":"56 Weeks"},{"measure":"Change From Baseline in Percent Body Surface Area (BSA) at Each Time Point","description":"The Investigator will calculate the percentage (%) of the total body surface area affected by AD.","timeFrame":"56 Weeks"},{"measure":"Pruritus Numerical Rating Scale (NRS) Score at Each Time Point","description":"The worst degree of itch experienced during 24 hours before the time point will be assessed on a Numerical Rating Scale. The degree of itch will be scored on an 11-point scale, with 0 being "no itch" and 10 being the "worst itch imaginable."","timeFrame":"56 Weeks"},{"measure":"Percent Change From Baseline in Pruritus Numerical Rating Scale (NRS) Score at Each Time Point","description":"The worst degree of itch experienced during 24 hours before the time point will be assessed on a Numerical Rating Scale. The degree of itch will be scored on an 11-point scale, with 0 being "no itch" and 10 being the "worst itch imaginable."","timeFrame":"56 Weeks"},{"measure":"Sleep Disturbance Numerical Rating Scale (NRS) Score at Each Time Point","description":"Daily sleep disturbance in the last 24 hours before the relevant time point will be assessed on a Numerical Rating Scale. Subjects will score the degree of their sleep disturbance on an 11-point scale ranging from 'no sleep loss' (0) to 'I cannot sleep at all' (10).","timeFrame":"56 Weeks"},{"measure":"Percent Change From Baseline in Sleep Disturbance Numerical Rating Scale (NRS) Score at Each Time Point","description":"Daily sleep disturbance in the last 24 hours before the relevant time point will be assessed on a Numerical Rating Scale. Subjects will score the degree of their sleep disturbance on an 11-point scale ranging from 'no sleep loss' (0) to 'I cannot sleep at all' (10).","timeFrame":"56 Weeks"},{"measure":"Dermatology Life Quality Index (DLQI) at Each Time Point","description":"DLQI consists of 6 subscales (symptoms and feelings, daily activities, leisure, work and school, personal relationships, and treatment), which are scored from 0 to 3 on the basis of 10 questions. The DLQI is calculated by summing the score of each question resulting in a maximum of 30 and a minimum of 0. The higher the score, the more QoL is impaired.","timeFrame":"56 Weeks"}]},"eligibilityModule":{"eligibilityCriteria":"Inclusion Criteria:

* Voluntarily signed informed consent to participate in the study;
* Chronic AD, according to American Academy of Dermatology Consensus Criteria or the local diagnostic criteria, that has been present for at least 1 year before screening;
* EASI score ≥16 at screening and baseline;
* IGA score ≥3 (moderate) at both screening and baseline;
* BSA ≥10% at both screening and baseline;
* Documented recent history (within 1 year prior to screening visit) of inadequate response to treatment with topical medications or for whom topical treatments are otherwise medically inadvisable (e.g., because of important side effects or safety risks).

Exclusion Criteria:

* Current or past history of clinically significant illness(es) deemed by the Investigator to be likely to affect the study conduct and assessments. Examples include, but are not limited to, clinically significant cardiovascular (e.g., New York Heart Association \[NYHA\] Class III or IV), uncontrolled diabetes (HbA1c ≥9%), liver (e.g., Child-Pugh class B or C), renal, respiratory, hematologic, central nervous system, psychiatric, or autoimmune diseases/disorders;
* Any of the following laboratory abnormalities at screening:

  * Serum creatinine: \>1.5 mg/dL
  * AST or ALT: ≥2.5 times the upper limit of normal (ULN)
  * Neutrophil count: \<1.5×10³/μL
  * Other laboratory abnormalities that may affect the completion or evaluation of the study, as judged by the Investigator;
* Active malignancies, or onset or a history of treatment of malignancies within 5 years prior to informed consent (except curatively treated in situ cervical carcinoma, cutaneous basal cell carcinoma, or cutaneous squamous cell carcinoma).","healthyVolunteers":false,"sex":"ALL","minimumAge":"18 Years","stdAges":["ADULT","OLDER_ADULT"]},"contactsLocationsModule":{"overallOfficials":[{"name":"Ehsanollah Esfandiari, MD, PhD","affiliation":"Kyowa Kirin Pharmaceutical International Ltd.","role":"STUDY_DIRECTOR"}],"locations":[{"facility":"Kyowa Investigational Site US-19","city":"Huntington Beach","state":"California","zip":"92647","country":"United States","geoPoint":{"lat":33.6603,"lon":-117.99923}},{"facility":"Kyowa Investigational Site US-17","city":"Irvine","state":"California","zip":"92697","country":"United States","geoPoint":{"lat":33.66946,"lon":-117.82311}},{"facility":"Kyowa Investigational Site US-09","city":"Los Angeles","state":"California","zip":"90033","country":"United States","geoPoint":{"lat":34.05223,"lon":-118.24368}},{"facility":"Kyowa Investigational Site US-05","city":"Santa Ana","state":"California","zip":"92701","country":"United States","geoPoint":{"lat":33.74557,"lon":-117.86783}},{"facility":"Kyowa Investigational Site US-10","city":"Aurora","state":"Colorado","zip":"80010","country":"United States","geoPoint":{"lat":39.72943,"lon":-104.83192}},{"facility":"Kyowa Investigational Site US-14","city":"Clearwater","state":"Florida","zip":"33756","country":"United States","geoPoint":{"lat":27.96585,"lon":-82.8001}},{"facility":"Kyowa Investigational Site US-04","city":"Boston","state":"Massachusetts","zip":"02115","country":"United States","geoPoint":{"lat":42.35843,"lon":-71.05977}},{"facility":"Kyowa Investigational Site US-01","city":"New York","state":"New York","zip":"10029","country":"United States","geoPoint":{"lat":40.71427,"lon":-74.00597}},{"facility":"Kyowa Investigational Site US-20","city":"Charlotte","state":"North Carolina","zip":