        "<table ID=\"Table1\"><caption>Table 1: RINVOQ/RINVOQ LQ Dosage for Pediatric Patients 2 Years to Less Than 18 Years of Age with Psoriatic Arthritis </caption><col width=\"126\"/><col width=\"264\"/><col width=\"252\"/><tbody><tr><td styleCode=\"Toprule Lrule Rrule \"><content styleCode=\"xmChange\"><content styleCode=\"bold\">Patient Weight</content></content></td><td styleCode=\"Toprule Lrule Rrule \"><content styleCode=\"xmChange\"><content styleCode=\"bold\">RINVOQ LQ</content></content></td><td styleCode=\"Toprule Lrule Rrule \"><content styleCode=\"xmChange\"><content styleCode=\"bold\">RINVOQ</content></content></td></tr><tr><td styleCode=\"Toprule Lrule Rrule \"><content styleCode=\"xmChange\">10 kg to less than 20 kg</content></td><td styleCode=\"Toprule Lrule Rrule \"><content styleCode=\"xmChange\">3 mg (3 mL oral solution) twice daily </content></td><td styleCode=\"Toprule Lrule Rrule \"><content styleCode=\"xmChange\">Not recommended</content></td></tr><tr><td styleCode=\"Toprule Lrule Rrule \"><content styleCode=\"xmChange\">20 kg to less than 30 kg</content></td><td styleCode=\"Toprule Lrule Rrule \"><content styleCode=\"xmChange\">4 mg (4 mL oral solution) twice daily</content></td><td styleCode=\"Toprule Lrule Rrule \"><content styleCode=\"xmChange\">Not recommended</content></td></tr><tr><td styleCode=\"Toprule Lrule Rrule \"><content styleCode=\"xmChange\">30 kg and greater</content></td><td styleCode=\"Toprule Lrule Rrule \"><content styleCode=\"xmChange\">6 mg (6 mL oral solution) twice daily </content></td><td styleCode=\"Toprule Lrule Rrule \"><content styleCode=\"xmChange\">15 mg (one 15 mg tablet) once daily</content></td></tr></tbody></table>",
        "<table ID=\"Table2\"><caption>Table 2: RINVOQ/RINVOQ LQ Dosage for Patients 2 years and older with pJIA</caption><col width=\"125\"/><col width=\"266\"/><col width=\"250\"/><tbody><tr><td styleCode=\"Toprule Lrule Rrule \"><content styleCode=\"xmChange\"><content styleCode=\"bold\">Patient Weight</content></content></td><td styleCode=\"Toprule Lrule Rrule \"><content styleCode=\"xmChange\"><content styleCode=\"bold\">RINVOQ LQ</content></content></td><td styleCode=\"Toprule Lrule Rrule \"><content styleCode=\"xmChange\"><content styleCode=\"bold\">RINVOQ</content></content></td></tr><tr><td styleCode=\"Toprule Lrule Rrule \"><content styleCode=\"xmChange\">10 kg to less than 20 kg</content></td><td styleCode=\"Toprule Lrule Rrule \"><content styleCode=\"xmChange\">3 mg (3 mL oral solution) twice daily </content></td><td styleCode=\"Toprule Lrule Rrule \"><content styleCode=\"xmChange\">Not recommended</content></td></tr><tr><td styleCode=\"Toprule Lrule Rrule \"><content styleCode=\"xmChange\">20 kg to less than 30 kg</content></td><td styleCode=\"Toprule Lrule Rrule \"><content styleCode=\"xmChange\">4 mg (4 mL oral solution) twice daily</content></td><td styleCode=\"Toprule Lrule Rrule \"><content styleCode=\"xmChange\">Not recommended</content></td></tr><tr><td styleCode=\"Toprule Lrule Rrule \"><content styleCode=\"xmChange\">30 kg and greater</content></td><td styleCode=\"Toprule Lrule Rrule \"><content styleCode=\"xmChange\">6 mg (6 mL oral solution) twice daily </content></td><td styleCode=\"Toprule Lrule Rrule \"><content styleCode=\"xmChange\">15 mg (one 15 mg tablet) once daily</content></td></tr></tbody></table>",
        "<table><caption>Table 3: Recommended Dosage Interruptions for Laboratory Abnormalities</caption><col width=\"250\"/><col width=\"376\"/><tbody><tr><td styleCode=\"Toprule Lrule Rrule \" align=\"center\"><content styleCode=\"bold\">Laboratory Measure</content></td><td styleCode=\"Toprule Lrule Rrule \" align=\"center\"><content styleCode=\"bold\">Action</content></td></tr><tr><td styleCode=\"Toprule Lrule Rrule \">Absolute Neutrophil Count (ANC)</td><td styleCode=\"Toprule Lrule Rrule \">Interrupt treatment if ANC is less than 1000 cells/mm<sup>3</sup>; treatment may be restarted once ANC returns above this value </td></tr><tr><td styleCode=\"Toprule Lrule Rrule \">Absolute Lymphocyte Count (ALC)</td><td styleCode=\"Toprule Lrule Rrule \">Interrupt treatment if ALC is less than 500 cells/mm<sup>3</sup>; treatment may be restarted once ALC returns above this value </td></tr><tr><td styleCode=\"Toprule Lrule Rrule \">Hemoglobin (Hb)</td><td styleCode=\"Toprule Lrule Rrule \">Interrupt treatment if Hb is less than 8 g/dL; treatment may be restarted once Hb returns above this value</td></tr><tr><td styleCode=\"Toprule Lrule Rrule \">Hepatic transaminases</td><td styleCode=\"Toprule Lrule Rrule \">Interrupt treatment if drug-induced liver injury is suspected, until this diagnosis is excluded. </td></tr></tbody></table>"
